    "fu.tx.head": L("Escolha o encaminhamento", "Choose the referral", "Elige la derivación"),
    "fu.tx.psico": L("Psicoterapia contínua", "Ongoing psychotherapy", "Psicoterapia continua"),
    "fu.tx.psicpsiq": L("Psicoterapia + avaliação psiquiátrica", "Psychotherapy + psychiatric evaluation", "Psicoterapia + evaluación psiquiátrica"),
    "fu.tx.familia": L("Orientação à família e à escola + acompanhamento", "Family and school guidance + follow-up", "Orientación a la familia y la escuela + seguimiento"),
    "fu.tx.grupo": L("Grupo de apoio e serviço especializado + acompanhamento", "Support group and specialized service + follow-up", "Grupo de apoyo y servicio especializado + seguimiento"),
    "fu.txwhy.psico": L("Indicada quando o quadro responde bem à psicoterapia e não há sinais de risco nem de sintomas que peçam avaliação médica.", "Fits when the condition responds well to psychotherapy and there are no signs of risk or of symptoms calling for a medical evaluation.", "Indicada cuando el cuadro responde bien a la psicoterapia y no hay señales de riesgo ni síntomas que pidan evaluación médica."),
    "fu.txwhy.psicpsiq": L("Indicada quando há sintomas intensos, prejuízo grande ou risco: o psiquiatra avalia se medicação é necessária. Quem prescreve é o médico, nunca o psicólogo.", "Fits when symptoms are intense, impairment is large or there is risk: the psychiatrist evaluates whether medication is needed. The doctor prescribes, never the psychologist.", "Indicada cuando hay síntomas intensos, gran deterioro o riesgo: el psiquiatra evalúa si hace falta medicación. Quien receta es el médico, nunca el psicólogo."),
    "fu.txwhy.familia": L("Em crianças e adolescentes o ambiente faz parte do tratamento: orientar a família e a escola costuma ser tão importante quanto a terapia.", "With children and teens the environment is part of the treatment: guiding family and school is often as important as therapy itself.", "En niños y adolescentes el entorno es parte del tratamiento: orientar a la familia y a la escuela suele ser tan importante como la terapia."),
    "fu.txwhy.grupo": L("Indicado no uso problemático de álcool e outras substâncias: serviços especializados e grupos de apoio sustentam a mudança.", "Fits problematic use of alcohol and other substances: specialized services and support groups sustain change.", "Indicado en el uso problemático de alcohol y otras sustancias: los servicios especializados y los grupos de apoyo sostienen el cambio."),
    "fu.tx.answer": L("O encaminhamento mais indicado era: {name}.", "The best-fitting referral was: {name}.", "La derivación más indicada era: {name}."),
