    "fu.result": L("Consulta {n} de {total}. Evolução do paciente até agora: {p}%.", "Session {n} of {total}. Patient's progress so far: {p}%.", "Consulta {n} de {total}. Evolución del paciente hasta ahora: {p}%."),
    "fu.weekroll": L("Semana {n} concluída! A semana {m} começa na segunda-feira. Pacientes em terapia com você renderam {c} moedas.", "Week {n} done! Week {m} starts on Monday. Patients in therapy with you earned {c} coins.", "¡Semana {n} completada! La semana {m} empieza el lunes. Los pacientes en terapia contigo aportaron {c} monedas."),
    "fu.toast.invite": L("📱 {name} mandou uma mensagem pedindo terapia.", "📱 {name} sent a message asking for therapy.", "📱 {name} envió un mensaje pidiendo terapia."),
